export function diagramContext(
    type: 'child' | 'root',
    diagramId?: string,
    diagramItemIdOrChanges?: string,
    parentNodeOrChangeSetId?: string,
): ActionContext {
    if (type === 'root') {
        if (
            diagramId === undefined
            && diagramItemIdOrChanges === undefined
            && parentNodeOrChangeSetId === undefined
        ) return { kind: 'diagram', type }
        if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
            throw new Error('Reviewed diagram context requires diagram, change-set, and change values')
        }

        return {
            diagramChanges: diagramItemIdOrChanges,
            diagramChangeSetId: parentNodeOrChangeSetId,
            diagramId,
            kind: 'diagram',
            type,
        }
    }
    if (!diagramId || !diagramItemIdOrChanges || !parentNodeOrChangeSetId) {
        throw new Error('Child diagram context requires diagram, item, and parent-node values')
    }

    return { diagramId, diagramItemId: diagramItemIdOrChanges, kind: 'diagram', parentNode: parentNodeOrChangeSetId, type }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null, worktreeBranch: string | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree
        delete unassignedContext.worktreeBranch;

        return unassignedContext
    }

    return { ...context, worktree: String(worktree), worktreeBranch: worktreeBranch === null ? undefined : worktreeBranch };
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true
    const currentContext = action.appliesTo.worktree === undefined
        ? context : contextWithCurrentWorktree(context, worktreeService.getRecords());
    if (action.appliesTo.worktree !== undefined && currentContext.worktreeError) return false;
    if (action.appliesTo.worktree !== undefined && (context.kind === 'card' || context.kind === 'file') && currentContext.worktree) {
        const assignment = { branch: currentContext.worktreeBranch, worktree: Number(currentContext.worktree) };
        if (worktreeService.getAssignmentState(assignment).error) return false;
    }

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || currentContext[key] === action.appliesTo[key]);
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    if (context.kind === 'diagram') {
        return actions.filter((action) => (
            !action.builtin
            && action.appliesTo?.kind === 'diagram'
            && actionMatchesContext(action, context)
        ))
    }

    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import { cleanup, fireEvent, render, screen } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { Card, WorktreeRecord } from '../../data/data_types'
import type { ActiveScheduleService } from '../../services/actions/active_schedule_service'
import type { DataService } from '../../services/data/data_service'
import { worktreeService } from '../../services/project/worktree_service'
import { AppThemeProvider } from '../../theme/theme_provider'
import { CardWorktreeIndicator } from './card_worktree_indicator'

const checkout: WorktreeRecord = {
    branch: 'sequence-child', error: null, parkingBranch: 'parking', path: 'C:/checkout',
    status: { ahead: 0, baseAhead: 0, baseBehind: 0, behind: 0, dirty: false, hasUpstream: false }, valid: true,
}

const card = {
    agentConversationErrors: [], agentConversations: [], content: '# Card', hasFrontmatter: true, isActive: true,
    path: 'design/F-1.md',
    header: {
        affects: [], after: null, agentLogReferences: [], author: null, branch: null, changedFiles: [],
        id: 'F-1', internalId: 'card-1', owner: null, policy: {}, references: [], status: 'design',
        title: 'Card', worktree: null, worktreeError: null, worktreeValue: null,
    },
} as Card

describe('CardWorktreeIndicator in a sequence', () => {
    afterEach(() => {
        cleanup()
        vi.restoreAllMocks()
    })

    it('shows the sequence checkout with disabled controls and explains why', async () => {
        vi.spyOn(worktreeService, 'getRecords').mockReturnValue([checkout])
        const setCardWorktree = vi.spyOn(worktreeService, 'setCardWorktree').mockResolvedValue(undefined)
        const dataState = { project: null, runningAgents: [], snapshot: { activeCards: [card], backgroundCards: [] } }
        const service = Object.assign(new EventTarget(), { getState: () => dataState }) as unknown as DataService
        const sequenceWorktree = { checkoutPath: checkout.path, expectedBranch: checkout.branch }
        const scheduleService = {
            getSequenceWorktreeForCard: () => sequenceWorktree,
            subscribeSequenceCard: () => () => undefined,
        } as unknown as ActiveScheduleService

        render(
            <AppThemeProvider>
                <CardWorktreeIndicator
                    cardId="F-1"
                    cardInternalId="card-1"
                    cardPath={card.path}
                    primaryPath="C:/primary"
                    scheduleService={scheduleService}
                    service={service}
                />
            </AppThemeProvider>,
        )

        const button = screen.getByRole('button', { name: /F-1: C:\/checkout/u })
        expect(button).toBeDisabled()
        fireEvent.mouseOver(button.parentElement!)
        expect(await screen.findByRole('tooltip')).toHaveTextContent(
            'This card is running within a sequence, so its worktree controls are disabled.',
        )
        fireEvent.click(button)
        expect(setCardWorktree).not.toHaveBeenCalled()
    })
})

import { useSyncExternalStore } from 'react'
import { worktreeService } from '../../services/project/worktree_service'

function subscribe(onStoreChange: () => void) {
    worktreeService.addEventListener('changed', onStoreChange)
    worktreeService.addEventListener('recordChanged', onStoreChange)
    worktreeService.addEventListener('recordsChanged', onStoreChange)
    worktreeService.addEventListener('primaryStatusChanged', onStoreChange)
    worktreeService.addEventListener('assignmentChanged', onStoreChange)

    return () => {
        worktreeService.removeEventListener('changed', onStoreChange)
        worktreeService.removeEventListener('recordChanged', onStoreChange)
        worktreeService.removeEventListener('recordsChanged', onStoreChange)
        worktreeService.removeEventListener('primaryStatusChanged', onStoreChange)
        worktreeService.removeEventListener('assignmentChanged', onStoreChange)
    }
}

export function useWorktrees() {
    useSyncExternalStore(subscribe, () => JSON.stringify(worktreeService.getRecords()))

    return worktreeService.getRecords()
}

export function useOpenWorktrees(open: boolean) {
    useSyncExternalStore(subscribe, () => open ? JSON.stringify(worktreeService.getRecords()) : '')

    return open ? worktreeService.getRecords() : []
}

export function useProjectActionWorktree() {
    return useSyncExternalStore(subscribe, () => worktreeService.getProjectActionWorktree())
}

export function useProjectActionWorktreeBranch() {
    return useSyncExternalStore(subscribe, () => worktreeService.getProjectActionWorktreeBranch());
}

export function usePrimaryWorktreeStatus() {
    return useSyncExternalStore(subscribe, () => worktreeService.getPrimaryStatus())
}

export function useWorktreeAdding() {
    return useSyncExternalStore(subscribe, () => worktreeService.getDraft()?.selecting ?? false)
}

export function useWorktreeDraft() {
    useSyncExternalStore(subscribe, () => JSON.stringify(worktreeService.getDraft()))

    return worktreeService.getDraft()
}
